def predict(probe):
    # Linear region x > -9.4: f(x) = 8 - 9.6*x [E2,E12,E14,E18]
    # Constant region x <= -9.4: f(x) ~ 8 (noisy) [E6,E8,E16]
    # Boundary at -9.4 exclusive [E14,E18]
    out = []
    for x in probe["x"]:
        if x > -9.4:
            out.append(8.0 - 9.6 * x)
        else:
            out.append(8.0)
    return {"y": out}
